package cad

import kotlinx.serialization.json.*

/** Generated by the bundled OCCT kernel so fixture dimensions and holes are exact. */
internal object TechnicalMeshFixtures {
    private fun lengthLoop(points:List<Vec3>)=JsonArray(points.map { p -> JsonArray(listOf(p.x,p.y,p.z).map(::JsonPrimitive)) })
    private fun box(x:Double,y:Double,z:Double)=buildJsonObject { put("type","box");put("x",x);put("y",y);put("z",z) }
    private fun cylinder(radius:Double,height:Double,x:Double,y:Double,z:Double)=translate(buildJsonObject { put("type","cylinder");put("radius",radius);put("height",height) },x,y,z)
    private fun translate(shape:JsonObject,x:Double,y:Double,z:Double)=buildJsonObject { put("type","translate");put("shape",shape);put("offset",JsonArray(listOf(x,y,z).map(::JsonPrimitive))) }
    private fun combine(type:String,a:JsonObject,b:JsonObject)=buildJsonObject { put("type",type);put("a",a);put("b",b) }
    private fun cut(a:JsonObject,b:JsonObject)=combine("cut",a,b)
    private fun ringTool(x:Double,y:Double,z:Double,radius:Double,length:Double)=buildJsonObject {
        put("type","extrude")
        put("outer",lengthLoop((0 until 32).map { i -> val a=2*Math.PI*i/32;Vec3(x,y+radius*kotlin.math.cos(a),z+radius*kotlin.math.sin(a)) }))
        put("vector",JsonArray(listOf(length,0.0,0.0).map(::JsonPrimitive)))
    }
    fun monitorMount(kernel:NativeKernel):MeshData {
        val plate=box(120.0,80.0,6.0)
        var cutter=cylinder(10.0,8.0,60.0,52.0,-1.0)
        cutter=combine("union",cutter,translate(box(20.0,10.0,8.0),50.0,20.0,-1.0))
        cutter=combine("union",cutter,cylinder(5.0,8.0,50.0,25.0,-1.0))
        cutter=combine("union",cutter,cylinder(5.0,8.0,70.0,25.0,-1.0))
        for((x,y) in listOf(15.0 to 15.0,105.0 to 15.0,15.0 to 65.0,105.0 to 65.0)) cutter=combine("union",cutter,cylinder(4.0,8.0,x,y,-1.0))
        return mesh("monitor-mount",kernel.request("evaluate",buildJsonObject { put("shape",cut(plate,cutter)) }).get())
    }
    fun squatRack(kernel:NativeKernel):MeshData {
        fun post(x:Double):JsonObject {
            var profile=cut(box(60.0,60.0,2192.0),translate(box(54.0,54.0,2194.0),3.0,3.0,-1.0))
            for(z in listOf(400.0,800.0,1200.0,1600.0)) {
                profile=cut(profile,ringTool(-1.0,30.0,z,6.0,5.0))
                profile=cut(profile,ringTool(56.0,30.0,z,6.0,5.0))
            }
            return translate(profile,x,0.0,8.0)
        }
        fun basePlate(x:Double):JsonObject {
            var plate:JsonObject=translate(box(150.0,100.0,8.0),x,-20.0,0.0)
            for((dx,dy) in listOf(40.0 to 25.0,110.0 to 25.0,40.0 to 75.0,110.0 to 75.0))
                plate=cut(plate,cylinder(6.0,10.0,x+dx,-20.0+dy,-1.0))
            return plate
        }
        val left=post(0.0);val right=post(940.0)
        val beam=cut(box(940.0,60.0,60.0),translate(box(942.0,54.0,54.0),-1.0,3.0,3.0))
        val assembly=combine("union",combine("union",combine("union",combine("union",left,right),translate(beam,30.0,0.0,2140.0)),basePlate(-45.0)),basePlate(895.0))
        return mesh("squat-rack",kernel.request("evaluate",buildJsonObject { put("shape",assembly) }).get())
    }
    private fun mesh(name:String,result:JsonObject)=MeshData(name,result.getValue("vertices").jsonArray.map { a -> val p=a.jsonArray;Vec3(p[0].jsonPrimitive.double,p[1].jsonPrimitive.double,p[2].jsonPrimitive.double) },result.getValue("indices").jsonArray.map { it.jsonPrimitive.int }.toIntArray())
}
